import { beforeEach, describe, expect, it } from "vitest";
import request from "supertest";
import { createApp } from "../src/app.ts";
import { resetUsers } from "../src/store/users.ts";
import { resetIdempotency } from "../src/lib/idempotency.ts";

const app = createApp();

function expectProblem(res: request.Response, status: number): void {
  expect(res.status).toBe(status);
  expect(res.headers["content-type"]).toMatch(/application\/problem\+json/);
  expect(res.body.status).toBe(status);
  expect(typeof res.body.type).toBe("string");
  expect(typeof res.body.title).toBe("string");
  expect(typeof res.body.detail).toBe("string");
  expect(typeof res.body.instance).toBe("string");
}

async function createUser(body: Record<string, unknown>): Promise<request.Response> {
  return request(app).post("/v1/users").send(body);
}

beforeEach(() => {
  resetUsers();
  resetIdempotency();
});

describe("POST /v1/users", () => {
  it("creates a user with default role", async () => {
    const res = await createUser({ email: "a@example.com", name: "Alice" });
    expect(res.status).toBe(201);
    expect(res.body.id).toMatch(/^[0-9a-f-]{36}$/);
    expect(res.body.email).toBe("a@example.com");
    expect(res.body.name).toBe("Alice");
    expect(res.body.role).toBe("member");
    expect(new Date(res.body.createdAt).toISOString()).toBe(res.body.createdAt);
    expect(res.body.updatedAt).toBe(res.body.createdAt);
  });

  it("accepts an explicit role", async () => {
    const res = await createUser({ email: "b@example.com", name: "Bob", role: "admin" });
    expect(res.status).toBe(201);
    expect(res.body.role).toBe("admin");
  });

  it("rejects duplicate email case-insensitively with 409", async () => {
    await createUser({ email: "dup@example.com", name: "One" });
    const res = await createUser({ email: "DUP@example.com", name: "Two" });
    expectProblem(res, 409);
  });

  it.each([
    [{ name: "No email" }],
    [{ email: "not-an-email", name: "X" }],
    [{ email: "x@example.com" }],
    [{ email: "x@example.com", name: "" }],
    [{ email: "x@example.com", name: "a".repeat(101) }],
    [{ email: "x@example.com", name: "X", role: "owner" }],
    [[]],
  ])("rejects invalid body %j with 422", async (body) => {
    const res = await request(app).post("/v1/users").send(body);
    expectProblem(res, 422);
  });

  it("ignores client-supplied id", async () => {
    const res = await createUser({ email: "c@example.com", name: "C", id: "00000000-0000-4000-8000-000000000000" });
    expect(res.status).toBe(201);
    expect(res.body.id).not.toBe("00000000-0000-4000-8000-000000000000");
  });

  it("replays with the same Idempotency-Key and body", async () => {
    const body = { email: "idem@example.com", name: "Idem" };
    const first = await request(app).post("/v1/users").set("Idempotency-Key", "k1").send(body);
    const second = await request(app).post("/v1/users").set("Idempotency-Key", "k1").send(body);
    expect(first.status).toBe(201);
    expect(second.status).toBe(201);
    expect(second.body).toEqual(first.body);
    const list = await request(app).get("/v1/users");
    expect(list.body.data).toHaveLength(1);
  });

  it("409s when Idempotency-Key is reused with a different body", async () => {
    await request(app).post("/v1/users").set("Idempotency-Key", "k2").send({ email: "a1@example.com", name: "A" });
    const res = await request(app).post("/v1/users").set("Idempotency-Key", "k2").send({ email: "a2@example.com", name: "A" });
    expectProblem(res, 409);
  });
});

describe("GET /v1/users", () => {
  it("lists users with default pagination", async () => {
    await createUser({ email: "a@example.com", name: "A" });
    await createUser({ email: "b@example.com", name: "B" });
    const res = await request(app).get("/v1/users");
    expect(res.status).toBe(200);
    expect(res.body.data).toHaveLength(2);
    expect(res.body.nextCursor).toBeNull();
  });

  it("paginates with cursor and limit", async () => {
    for (let i = 0; i < 5; i++) await createUser({ email: `u${i}@example.com`, name: `U${i}` });
    const page1 = await request(app).get("/v1/users?limit=2");
    expect(page1.status).toBe(200);
    expect(page1.body.data).toHaveLength(2);
    expect(typeof page1.body.nextCursor).toBe("string");
    const page2 = await request(app).get(`/v1/users?limit=2&cursor=${page1.body.nextCursor}`);
    expect(page2.body.data).toHaveLength(2);
    expect(page2.body.data[0].email).toBe("u2@example.com");
    const page3 = await request(app).get(`/v1/users?limit=2&cursor=${page2.body.nextCursor}`);
    expect(page3.body.data).toHaveLength(1);
    expect(page3.body.nextCursor).toBeNull();
  });

  it("filters by role", async () => {
    await createUser({ email: "a@example.com", name: "A", role: "admin" });
    await createUser({ email: "b@example.com", name: "B" });
    const res = await request(app).get("/v1/users?role=admin");
    expect(res.status).toBe(200);
    expect(res.body.data).toHaveLength(1);
    expect(res.body.data[0].role).toBe("admin");
  });

  it.each(["limit=0", "limit=101", "limit=-1", "limit=abc", "role=owner", "cursor=bm9wZQ"])(
    "rejects bad query %s with 422",
    async (qs) => {
      const res = await request(app).get(`/v1/users?${qs}`);
      expectProblem(res, 422);
    },
  );
});

describe("GET /v1/users/:id", () => {
  it("returns a user", async () => {
    const created = await createUser({ email: "a@example.com", name: "A" });
    const res = await request(app).get(`/v1/users/${created.body.id}`);
    expect(res.status).toBe(200);
    expect(res.body).toEqual(created.body);
  });

  it("404s for unknown id", async () => {
    const res = await request(app).get("/v1/users/00000000-0000-4000-8000-000000000000");
    expectProblem(res, 404);
  });

  it("422s for malformed id", async () => {
    const res = await request(app).get("/v1/users/not-a-uuid");
    expectProblem(res, 422);
  });
});

describe("PATCH /v1/users/:id", () => {
  it("partially updates", async () => {
    const created = await createUser({ email: "a@example.com", name: "A" });
    await new Promise((r) => setTimeout(r, 5));
    const res = await request(app).patch(`/v1/users/${created.body.id}`).send({ name: "Renamed", role: "viewer" });
    expect(res.status).toBe(200);
    expect(res.body.name).toBe("Renamed");
    expect(res.body.role).toBe("viewer");
    expect(res.body.email).toBe("a@example.com");
    expect(res.body.createdAt).toBe(created.body.createdAt);
    expect(res.body.updatedAt).not.toBe(created.body.updatedAt);
  });

  it("allows changing email to a new address and keeping own email with different case", async () => {
    const created = await createUser({ email: "a@example.com", name: "A" });
    const same = await request(app).patch(`/v1/users/${created.body.id}`).send({ email: "A@example.com" });
    expect(same.status).toBe(200);
    const res = await request(app).patch(`/v1/users/${created.body.id}`).send({ email: "new@example.com" });
    expect(res.status).toBe(200);
    expect(res.body.email).toBe("new@example.com");
  });

  it("409s on email clash", async () => {
    await createUser({ email: "a@example.com", name: "A" });
    const b = await createUser({ email: "b@example.com", name: "B" });
    const res = await request(app).patch(`/v1/users/${b.body.id}`).send({ email: "A@EXAMPLE.com" });
    expectProblem(res, 409);
  });

  it("422s on invalid body", async () => {
    const created = await createUser({ email: "a@example.com", name: "A" });
    const res = await request(app).patch(`/v1/users/${created.body.id}`).send({ role: "owner" });
    expectProblem(res, 422);
  });

  it("404s for unknown id", async () => {
    const res = await request(app).patch("/v1/users/00000000-0000-4000-8000-000000000000").send({ name: "X" });
    expectProblem(res, 404);
  });

  it("422s for malformed id", async () => {
    const res = await request(app).patch("/v1/users/bad").send({ name: "X" });
    expectProblem(res, 422);
  });

  it("replays with the same Idempotency-Key", async () => {
    const created = await createUser({ email: "a@example.com", name: "A" });
    const url = `/v1/users/${created.body.id}`;
    const first = await request(app).patch(url).set("Idempotency-Key", "p1").send({ name: "N" });
    const second = await request(app).patch(url).set("Idempotency-Key", "p1").send({ name: "N" });
    expect(first.status).toBe(200);
    expect(second.status).toBe(200);
    expect(second.body).toEqual(first.body);
  });
});

describe("DELETE /v1/users/:id", () => {
  it("deletes a user", async () => {
    const created = await createUser({ email: "a@example.com", name: "A" });
    const res = await request(app).delete(`/v1/users/${created.body.id}`);
    expect(res.status).toBe(204);
    expect(res.text).toBe("");
    const after = await request(app).get(`/v1/users/${created.body.id}`);
    expectProblem(after, 404);
  });

  it("frees the email after delete", async () => {
    const created = await createUser({ email: "a@example.com", name: "A" });
    await request(app).delete(`/v1/users/${created.body.id}`);
    const res = await createUser({ email: "a@example.com", name: "A2" });
    expect(res.status).toBe(201);
  });

  it("404s for unknown id", async () => {
    const res = await request(app).delete("/v1/users/00000000-0000-4000-8000-000000000000");
    expectProblem(res, 404);
  });

  it("422s for malformed id", async () => {
    const res = await request(app).delete("/v1/users/bad");
    expectProblem(res, 422);
  });
});

describe("unknown routes", () => {
  it("404s as problem+json", async () => {
    const res = await request(app).get("/v1/nope");
    expectProblem(res, 404);
  });
});

