  40|   if (err instanceof HttpProblem) {
  41|     sendProblem(req, res, err.status, err.title, err.message, err.slug);
  42|   } else if (err instanceof ZodError) {
  43|     const detail = err.issues.map((i) => `${i.path.join(".") || "(root)"}: ${i.message}`).join("; ");
  44|     sendProblem(req, res, 422, "Request failed validation", detail, "validation");
  45|   } else if (err instanceof SyntaxError && "body" in err) {
