   1| // Idempotency-Key support for unsafe methods (POST, PATCH).
   2| // Same key + same request => the first response is replayed.
   3| // Same key + different request => 409 problem.
   4| import { createHash } from "node:crypto";
   5| import type { RequestHandler } from "express";
   6| import { HttpProblem } from "./problem.ts";
   7| 
   8| const seen = new Map<string, { fingerprint: string; status: number; body: unknown }>();
   9| 
  10| export const idempotency: RequestHandler = (req, res, next) => {
  11|   const key = req.get("Idempotency-Key");
  12|   if (key === undefined) {
  13|     next();
  14|     return;
  15|   }
  16|   const scope = `${req.method} ${req.originalUrl} ${key}`;
  17|   const fingerprint = createHash("sha256").update(JSON.stringify(req.body ?? null)).digest("hex");
  18|   const prior = seen.get(scope);
  19|   if (prior) {
  20|     if (prior.fingerprint !== fingerprint) {
  21|       next(new HttpProblem(409, "Idempotency key reuse", "Idempotency-Key was already used with a different request"));
  22|       return;
  23|     }
  24|     res.status(prior.status).json(prior.body);
  25|     return;
  26|   }
  27|   const send = res.json.bind(res);
  28|   res.json = ((body: unknown) => {
  29|     if (res.statusCode < 400) seen.set(scope, { fingerprint, status: res.statusCode, body });
  30|     return send(body);
  31|   }) as typeof res.json;
  32|   next();
  33| };
  34| 
  35| export function resetIdempotency(): void {
  36|   seen.clear();
  37| }
