   1| // RFC 7807 problem details. The only place in the API that writes an error response.
   2| import type { ErrorRequestHandler, Request, RequestHandler, Response } from "express";
   3| import { ZodError } from "zod";
   4| 
   5| export const PROBLEM_BASE = "https://api.sf/problems/";
   6| 
   7| const SLUGS: Record<number, string> = {
   8|   400: "bad-request",
   9|   404: "not-found",
  10|   409: "conflict",
  11|   422: "validation",
  12|   500: "internal",
  13| };
  14| 
  15| export class HttpProblem extends Error {
  16|   readonly status: number;
  17|   readonly title: string;
  18|   readonly slug: string;
  19| 
  20|   constructor(status: number, title: string, detail: string, slug?: string) {
  21|     super(detail);
  22|     this.status = status;
  23|     this.title = title;
  24|     this.slug = slug ?? SLUGS[status] ?? "error";
  25|   }
  26| }
  27| 
  28| export function sendProblem(req: Request, res: Response, status: number, title: string, detail: string, slug: string): void {
  29|   res
  30|     .status(status)
  31|     .type("application/problem+json")
  32|     .json({ type: PROBLEM_BASE + slug, title, status, detail, instance: req.originalUrl });
  33| }
  34| 
  35| export const notFound: RequestHandler = (req, res) => {
  36|   sendProblem(req, res, 404, "Not Found", `No route for ${req.method} ${req.path}`, "not-found");
  37| };
  38| 
  39| export const problemHandler: ErrorRequestHandler = (err: unknown, req, res, _next) => {
  40|   if (err instanceof HttpProblem) {
  41|     sendProblem(req, res, err.status, err.title, err.message, err.slug);
  42|   } else if (err instanceof ZodError) {
  43|     const detail = err.issues.map((i) => `${i.path.join(".") || "(root)"}: ${i.message}`).join("; ");
  44|     sendProblem(req, res, 422, "Request failed validation", detail, "validation");
  45|   } else if (err instanceof SyntaxError && "body" in err) {
  46|     sendProblem(req, res, 400, "Malformed JSON", err.message, "bad-request");
  47|   } else {
  48|     sendProblem(req, res, 500, "Internal Server Error", "Unexpected error", "internal");
  49|   }
  50| };
