  17|   readonly title: string;
  18|   readonly slug: string;
  19| 
  20|   constructor(status: number, title: string, detail: string, slug?: string) {
  21|     super(detail);
  22|     this.status = status;
  23|     this.title = title;
  24|     this.slug = slug ?? SLUGS[status] ?? "error";
  25|   }
  26| }
  27| 
  28| export function sendProblem(req: Request, res: Response, status: number, title: string, detail: string, slug: string): void {
  29|   res
  30|     .status(status)
  31|     .type("application/problem+json")
  32|     .json({ type: PROBLEM_BASE + slug, title, status, detail, instance: req.originalUrl });
  33| }
